package br.com.onda;
import android.app.ActivityManager;import android.content.*;import android.content.pm.*;import android.hardware.*;import android.net.*;import android.os.*;import java.io.*;import java.text.DateFormat;import java.util.*;
/** User-requested system snapshot only. No identifiers, inventory of other apps or background polling. */
final class DeviceReport {
 final LinkedHashMap<String,String> sections=new LinkedHashMap<>();
 static String unavailable="Não informado pelo Android";
 static String bytes(long n){return String.format(Locale.getDefault(),"%.1f GB",n/1073741824.0);}
 static String battery(Intent b){if(b==null)return unavailable;StringBuilder s=new StringBuilder();int level=b.getIntExtra(BatteryManager.EXTRA_LEVEL,-1),scale=b.getIntExtra(BatteryManager.EXTRA_SCALE,0);s.append("Carga: ").append(level>=0&&scale>0?Math.round(level*100f/scale)+"%":unavailable);if(b.hasExtra(BatteryManager.EXTRA_TEMPERATURE))s.append(String.format(Locale.getDefault(),"\nTemperatura informada: %.1f °C",b.getIntExtra(BatteryManager.EXTRA_TEMPERATURE,0)/10f));if(b.hasExtra(BatteryManager.EXTRA_VOLTAGE))s.append("\nTensão informada: ").append(b.getIntExtra(BatteryManager.EXTRA_VOLTAGE,0)).append(" mV");int health=b.getIntExtra(BatteryManager.EXTRA_HEALTH,BatteryManager.BATTERY_HEALTH_UNKNOWN);String h=health==BatteryManager.BATTERY_HEALTH_GOOD?"Sem alerta informado":health==BatteryManager.BATTERY_HEALTH_OVERHEAT?"Alerta de temperatura":health==BatteryManager.BATTERY_HEALTH_DEAD?"Alerta de bateria":health==BatteryManager.BATTERY_HEALTH_OVER_VOLTAGE?"Alerta de tensão":health==BatteryManager.BATTERY_HEALTH_COLD?"Alerta de frio":unavailable;s.append("\nEstado comunicado: ").append(h);int plugged=b.getIntExtra(BatteryManager.EXTRA_PLUGGED,0);s.append("\nFonte: ").append(plugged==BatteryManager.BATTERY_PLUGGED_USB?"USB":plugged==BatteryManager.BATTERY_PLUGGED_AC?"Carregador":plugged==BatteryManager.BATTERY_PLUGGED_WIRELESS?"Sem fio":plugged==0?"Bateria":"Outra fonte");String technology=b.getStringExtra(BatteryManager.EXTRA_TECHNOLOGY);if(technology!=null)s.append("\nTecnologia: ").append(technology);s.append("\nCapacidade real, desgaste e vida útil: não determinados por esta leitura.");return s.toString();}
 static DeviceReport collect(Context c){DeviceReport report=new DeviceReport();String hardware="Fabricante: "+Build.MANUFACTURER+"\nModelo: "+Build.MODEL+"\nMarca: "+Build.BRAND+"\nProduto: "+Build.PRODUCT+"\nHardware informado: "+Build.HARDWARE+"\nArquiteturas: "+String.join(", ",Build.SUPPORTED_ABIS)+"\nNúcleos disponíveis ao app: "+Runtime.getRuntime().availableProcessors();if(Build.VERSION.SDK_INT>=31)hardware+="\nSoC: "+Build.SOC_MANUFACTURER+" "+Build.SOC_MODEL;report.sections.put("Aparelho e processador",hardware);
  ActivityManager.MemoryInfo memory=new ActivityManager.MemoryInfo();((ActivityManager)c.getSystemService(Context.ACTIVITY_SERVICE)).getMemoryInfo(memory);String resources="RAM informada: "+bytes(memory.totalMem)+"\nRAM disponível neste momento: "+bytes(memory.availMem)+"\nAlerta de pouca memória: "+(memory.lowMemory?"Sim":"Não");try{StatFs disk=new StatFs(c.getFilesDir().getAbsolutePath());resources+="\nVolume interno do app: "+bytes(disk.getTotalBytes())+"\nEspaço disponível nesse volume: "+bytes(disk.getAvailableBytes());}catch(RuntimeException e){resources+="\nArmazenamento: "+unavailable;}report.sections.put("Memória e armazenamento",resources);
  String software="Android: "+Build.VERSION.RELEASE+" (API "+Build.VERSION.SDK_INT+")\nAtualização de segurança: "+Build.VERSION.SECURITY_PATCH+"\nCompilação: "+Build.DISPLAY+"\nTempo desde a inicialização: "+android.text.format.DateUtils.formatElapsedTime(SystemClock.elapsedRealtime()/1000);try{PackageInfo own=c.getPackageManager().getPackageInfo(c.getPackageName(),0);software+="\nOnda: "+own.versionName+"\nPacote: "+c.getPackageName();}catch(PackageManager.NameNotFoundException ignored){}software+="\nAtualizações do sistema e de segurança: consulte também as configurações do fabricante.";report.sections.put("Android e Onda",software);
  report.sections.put("Bateria",battery(c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED))));PowerManager power=(PowerManager)c.getSystemService(Context.POWER_SERVICE);String saving="Economia de energia do sistema: "+(power.isPowerSaveMode()?"Ativa":"Inativa");if(Build.VERSION.SDK_INT>=29)saving+="\nNível térmico informado: "+thermal(power.getCurrentThermalStatus());saving+="\nTemperatura da bateria não representa a temperatura de todos os componentes.";report.sections.put("Energia e temperatura",saving);
  ConnectivityManager manager=(ConnectivityManager)c.getSystemService(Context.CONNECTIVITY_SERVICE);NetworkCapabilities net=manager.getNetworkCapabilities(manager.getActiveNetwork());String network="Rede ativa: "+(net==null?"Nenhuma":net.hasTransport(NetworkCapabilities.TRANSPORT_WIFI)?"Wi-Fi":net.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)?"Móvel":net.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET)?"Ethernet":net.hasTransport(NetworkCapabilities.TRANSPORT_VPN)?"VPN":"Outra");if(net!=null)network+="\nInternet validada pelo Android: "+(net.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)?"Sim":"Não confirmada")+"\nConexão tarifada: "+(manager.isActiveNetworkMetered()?"Sim":"Não");network+="\nBluetooth suportado: "+(c.getPackageManager().hasSystemFeature(PackageManager.FEATURE_BLUETOOTH)?"Sim":"Não informado")+"\nNão consulta nomes de redes, dispositivos pareados ou localização. A leitura não é um teste de velocidade.";report.sections.put("Conexões",network);
  SensorManager sensors=(SensorManager)c.getSystemService(Context.SENSOR_SERVICE);List<Sensor> list=sensors.getSensorList(Sensor.TYPE_ALL);StringBuilder inventory=new StringBuilder("Sensores anunciados pelo Android: "+list.size());for(Sensor sensor:list)inventory.append("\n• ").append(sensor.getName()).append(" — ").append(sensor.getVendor()).append(" (tipo ").append(sensor.getType()).append(")");report.sections.put("Sensores disponíveis",inventory.toString());return report;
 }
 static String thermal(int n){switch(n){case 0:return "Sem alerta";case 1:return "Leve";case 2:return "Moderado";case 3:return "Elevado";case 4:return "Crítico";case 5:return "Emergência";case 6:return "Desligamento térmico";default:return unavailable;}}
 String text(Map<String,String> tests){StringBuilder s=new StringBuilder("Onda • Meu smartphone\n"+DateFormat.getDateTimeInstance().format(new Date())+"\n\nLeitura informativa do Android, não é laudo técnico, antivírus ou medição de desgaste. Sem IMEI, número de série, contas ou lista de apps.\n");for(Map.Entry<String,String> entry:sections.entrySet())s.append("\n").append(entry.getKey()).append("\n").append(entry.getValue()).append("\n");s.append("\nTestes sob demanda\n");if(tests.isEmpty())s.append("Nenhum teste concluído.\n");for(Map.Entry<String,String> entry:tests.entrySet())s.append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");return s.toString();}
}
